import json, urllib.request, urllib.parse, os, time
from datetime import datetime, timedelta, timezone

BOT_TOKEN = ***"SLACK_BOT_TOKEN"]
BASE_URL = os.environ.get("SLACK_URL", "https://slack.com/api")

# Past week: Monday July 14 00:00 UTC to now (July 20 ~07:00 UTC)
# Using a broad window: 7 days back from now
now = datetime.now(timezone.utc)
week_ago = now - timedelta(days=7)
oldest = str(week_ago.timestamp())
latest = str(now.timestamp())

def api_call(endpoint, params=None):
    url = f"{BASE_URL}/api/{endpoint}"
    if params:
        url += "?" + urllib.parse.urlencode(params)
    req = urllib.Request(url, headers={"Authorization": ***REDACTED***"Bearer {BOT_TOKEN}"})
    with urllib.request.urlopen(req) as resp:
        return json.loads(resp.read())

# Step 1: Get all public channels
channels = []
cursor = None
while True:
    params = {"types": "public_channel", "limit": 200}
    if cursor:
        params["cursor"] = cursor
    data = api_call("conversations.list", params)
    if not data.get("ok"):
        print(f"Error listing channels: {data}")
        break
    for ch in data.get("channels", []):
        if not ch.get("is_archived"):
            channels.append({"id": ch["id"], "name": ch["name"]})
    cursor = data.get("response_metadata", {}).get("next_cursor")
    if not cursor:
        break

print(f"Found {len(channels)} non-archived public channels")

# Step 2: For each channel, get messages from the past week
# Then get reactions for each message
all_channels = channels  # process ALL channels

# Track: user -> total reaction count
user_reactions = {}  # user_id -> {"total_reactions": int, "messages": [{"channel": str, "ts": str, "text": str, "reactions": int}]}
user_names = {}

def get_user_info(user_id):
    if user_id in user_names:
        return user_names[user_id]
    try:
        data = api_call("users.info", {"user": user_id})
        if data.get("ok"):
            u = data["user"]
            name = u.get("real_name") or u.get("name") or user_id
            user_names[user_id] = name
            return name
    except:
        pass
    user_names[user_id] = user_id
    return user_id

total_messages = 0
total_with_reactions = 0

for ch in all_channels:
    ch_id = ch["id"]
    ch_name = ch["name"]
    print(f"\n--- Channel: #{ch_name} ({ch_id}) ---")

    # Join the channel first (bot needs to be in it to read)
    try:
        api_call("conversations.join", {"channel": ch_id})
    except:
        pass

    # Fetch messages
    messages = []
    cursor = None
    while True:
        params = {"channel": ch_id, "limit": 200, "oldest": oldest, "latest": latest}
        if cursor:
            params["cursor"] = cursor
        try:
            data = api_call("conversations.history", params)
        except Exception as e:
            print(f"  Error fetching history: {e}")
            break
        if not data.get("ok"):
            print(f"  Error: {data.get('error', 'unknown')}")
            break
        msgs = data.get("messages", [])
        messages.extend(msgs)
        cursor = data.get("response_metadata", {}).get("next_cursor")
        if not cursor:
            break

    print(f"  Found {len(messages)} messages in the past week")
    total_messages += len(messages)

    for msg in messages:
        if msg.get("subtype"):
            continue  # skip bot messages, joins, etc.
        user_id = msg.get("user")
        if not user_id:
            continue
        msg_ts = msg.get("ts")
        text = msg.get("text", "")[:200]
        reactions = msg.get("reactions", [])

        if reactions:
            total_with_reactions += 1

        total_reaction_count = 0
        reaction_details = []
        for r in reactions:
            count = r.get("count", 0)
            total_reaction_count += count
            reaction_details.append(f"{r.get('name')}×{count}")

        if total_reaction_count > 0:
            if user_id not in user_reactions:
                user_reactions[user_id] = {"total_reactions": 0, "messages": []}
            user_reactions[user_id]["total_reactions"] += total_reaction_count
            user_reactions[user_id]["messages"].append({
                "channel": ch_name,
                "ts": msg_ts,
                "text": text,
                "reactions": total_reaction_count,
                "details": ", ".join(reaction_details[:5])
            })

print(f"\n\n=== SUMMARY ===")
print(f"Total messages scanned: {total_messages}")
print(f"Messages with reactions: {total_with_reactions}")
print(f"Unique users with reactions: {len(user_reactions)}")

# Sort by total reactions
ranking = sorted(user_reactions.items(), key=lambda x: x[1]["total_reactions"], reverse=True)

print(f"\n=== REACTION LEADERBOARD (Past Week) ===")
for rank, (user_id, data) in enumerate(ranking[:10], 1):
    name = get_user_info(user_id)
    print(f"\n#{rank}: {name} ({user_id}) — {data['total_reactions']} reactions")
    for m in data["messages"][:3]:
        print(f"   #{m['channel']}: {m['text'][:80]}... [{m['details']}]")

# Save full results as JSON
result = {
    "week_range": f"{week_ago.isoformat()} to {now.isoformat()}",
    "total_messages": total_messages,
    "total_with_reactions": total_with_reactions,
    "ranking": [
        {
            "rank": i+1,
            "user_id": uid,
            "name": get_user_info(uid),
            "total_reactions": d["total_reactions"],
            "messages": d["messages"]
        }
        for i, (uid, d) in enumerate(ranking[:10])
    ]
}
with open("/tmp/slack_leaderboard.json", "w") as f:
    json.dump(result, f, indent=2)

print("\n\nFull results saved to /tmp/slack_leaderboard.json")
